function buildDayReport(date){
  const daySales=sales.filter(s=>s.businessDate===date&&saleTimeValue(s)>=businessDayStartedAtMs);
  const productMap=new Map(),quantityMap=new Map(),brews=new Map();
  for(const brew of [...teaState.activeBrews,...teaState.history]){if(getBrewBusinessDate(brew)===date&&(Number(brew.startedAtMs)||0)>=businessDayStartedAtMs)brews.set(brew.id||`${brew.startedAtMs}`,brew)}
  let salesTotal=0,cashTotal=0,transferTotal=0,tipTotal=0,roundingTotal=0,orderCount=0,itemCount=0,giftCount=0,merchantMarkaCount=0,merchantTopupTotal=0,merchantDeliveredTea=0;
  for(const sale of daySales){
    if(sale.recordType==='correction')continue;
    if(['merchant-topup','merchant-topup-correction'].includes(sale.recordType)){merchantMarkaCount+=Number(sale.markaCount)||0;merchantTopupTotal+=Number(sale.saleTotal)||0;salesTotal+=Number(sale.saleTotal)||0;cashTotal+=Number(sale.cashAmount)||0;transferTotal+=Number(sale.transferAmount)||0;continue}
    if(['merchant-delivery','merchant-manual-delivery'].includes(sale.recordType)){merchantDeliveredTea+=Number(sale.deliveredTeaCount)||0;continue}
    if(sale.recordType==='payment'){cashTotal+=Number(sale.cashAmount??sale.amount)||0;transferTotal+=Number(sale.transferAmount)||0;tipTotal+=Number(sale.tipAmount)||0;continue}
    if(sale.recordType==='credit-payment'){cashTotal+=Number(sale.cashAmount??sale.amount)||0;transferTotal+=Number(sale.transferAmount)||0;continue}
    if(sale.recordType==='credit-topup'){cashTotal+=Number(sale.cashAmount)||0;transferTotal+=Number(sale.transferAmount)||0;continue}
    const isSale=sale.recordType==='sale'||!sale.recordType;
    if(!isSale)continue;
    salesTotal+=Number(sale.baseTotal)||0;cashTotal+=Number(sale.cashAmount??sale.paymentAmount??sale.paidTotal)||0;transferTotal+=Number(sale.transferAmount)||0;tipTotal+=Number(sale.tipAmount)||0;roundingTotal+=(Number(sale.roundingDiscount)||Math.max(0,-(Number(sale.roundingAmount)||0)));orderCount++;
    for(const item of sale.items||[]){
      const qty=Number(item.quantity)||0;if(item.complimentary){giftCount+=qty;continue}itemCount+=qty;
      const exactKey=`${item.name}|${Number(item.unitPrice)||0}`,current=productMap.get(exactKey)||{name:item.name||'Ürün',quantity:0,unitPrice:Number(item.unitPrice)||0,total:0};current.quantity+=qty;current.total+=qty*current.unitPrice;productMap.set(exactKey,current);
      const name=String(item.name||'Ürün').trim()||'Ürün',quantityCurrent=quantityMap.get(name)||{name,quantity:0};quantityCurrent.quantity+=qty;quantityMap.set(name,quantityCurrent)
    }
  }
  const activeManualIncome=cashMovements.filter(m=>m.businessDate===date&&m.type==='income'&&m.automatic!==true),manualIncomeCash=activeManualIncome.filter(m=>m.account==='cash').reduce((sum,m)=>sum+(Number(m.amount)||0),0),manualIncomeBank=activeManualIncome.filter(m=>m.account==='bank').reduce((sum,m)=>sum+(Number(m.amount)||0),0);
  const products=[...productMap.values()].sort((a,b)=>a.name.localeCompare(b.name,'tr')),productQuantities=[...quantityMap.values()].sort((a,b)=>b.quantity-a.quantity||a.name.localeCompare(b.name,'tr'));
  return{businessDate:date,businessDayStartedAtMs,salesTotal,cashTotal,transferTotal,manualIncomeCash,manualIncomeBank,cashIncomeTotal:cashTotal+manualIncomeCash,bankIncomeTotal:transferTotal+manualIncomeBank,tipTotal,roundingTotal,orderCount,itemCount,giftCount,merchantMarkaCount,merchantTopupTotal,merchantDeliveredTea,brewedPotCount:brews.size,products,productQuantities}
}
function hasActiveBrews(state=teaState){return Array.isArray(state?.activeBrews)&&state.activeBrews.length>0}
function activeBrewWarning(state=teaState){const count=Array.isArray(state?.activeBrews)?state.activeBrews.length:0;return count===1?'Günü kapatmadan önce aktif demliği bitirin.':`Günü kapatmadan önce ${count} aktif demliği bitirin.`}

function cashMovementTimeValue(movement){return movement.updatedAt?.toMillis?.()||movement.createdAt?.toMillis?.()||Number(movement.updatedAtMs)||Number(movement.createdAtMs)||Number(movement.businessDayStartedAtMs)||0}
function stockMovementTimeValue(movement){return movement.createdAt?.toMillis?.()||Number(movement.createdAtMs)||Number(movement.businessDayStartedAtMs)||0}
function currentBusinessDayHasActivity(){
  const date=businessDate,start=businessDayStartedAtMs;
  if(orders.length)return true;
  if(sales.some(s=>s.businessDate===date&&saleTimeValue(s)>=start))return true;
  if(cashMovements.some(m=>m.businessDate===date&&!m.reversed&&cashMovementTimeValue(m)>=start))return true;
  if(stockMovements.some(m=>(m.businessDate||m.operationDate)===date&&stockMovementTimeValue(m)>=start))return true;
  if([...(teaState.activeBrews||[]),...(teaState.history||[])].some(b=>getBrewBusinessDate(b)===date&&(Number(b.startedAtMs)||0)>=start))return true;
  return false;
}
async function findUndoableClosing(){
  const snapshot=await getDocs(query(closingsCol,where('nextBusinessDate','==',businessDate)));
  const candidates=snapshot.docs.map(d=>({id:d.id,ref:d.ref,...d.data()})).filter(c=>Number(c.closedAtMs)===Number(businessDayStartedAtMs)||String(c.nextBusinessDate||'')===String(businessDate));
  if(!candidates.length)return null;
  candidates.sort((a,b)=>(Number(b.closedAtMs)||0)-(Number(a.closedAtMs)||0));
  const exact=candidates.find(c=>Number(c.closedAtMs)===Number(businessDayStartedAtMs));
  return exact||candidates[0];
}
function renderUndoLastCloseBox(state={loading:true}){
  if(!el.undoLastCloseBox)return;
  if(state.hidden){el.undoLastCloseBox.hidden=true;return}
  el.undoLastCloseBox.hidden=false;
  if(state.loading){el.undoLastCloseText.textContent='Son kapanış kontrol ediliyor…';el.undoLastCloseButton.disabled=true;return}
  const closing=state.closing;
  if(!closing){el.undoLastCloseBox.hidden=true;return}
  if(state.hasActivity){
    el.undoLastCloseBox.classList.add('is-locked');
    el.undoLastCloseText.textContent=`${formatDate(closing.businessDate)} kapanışı geri alınamaz. Yeni iş gününde işlem olduğu için kayıt güvenliği kilitlendi.`;
    el.undoLastCloseButton.disabled=true;
  }else{
    el.undoLastCloseBox.classList.remove('is-locked');
    el.undoLastCloseText.textContent=`Yanlışlıkla kapattıysan ${formatDate(closing.businessDate)} iş gününü geri açabilirsin. Yeni günde işlem varsa bu buton kilitlenir.`;
    el.undoLastCloseButton.disabled=false;
  }
}
async function refreshUndoLastCloseBox(){
  renderUndoLastCloseBox({loading:true});
  try{const closing=await findUndoableClosing();if(!closing){renderUndoLastCloseBox({hidden:true});return}renderUndoLastCloseBox({closing,hasActivity:currentBusinessDayHasActivity()})}catch(error){console.warn('Son kapanış kontrol edilemedi.',error);renderUndoLastCloseBox({hidden:true})}
}
async function undoLastBusinessDayClosing(){
  if(closingDayBusy)return;
  const closing=await findUndoableClosing();
  if(!closing){show('Geri alınabilecek son kapanış bulunamadı.');return}
  if(currentBusinessDayHasActivity()){show('Yeni iş gününde işlem olduğu için kapanış geri alınamaz.');await refreshUndoLastCloseBox();return}
  const ok=await requireSensitiveAccess({title:'Son Kapanışı Geri Al',message:`${formatDate(closing.businessDate)} iş gününü tekrar aktif etmek için yönetici PIN'ini girin.`});
  if(!ok)return;
  closingDayBusy=true;el.undoLastCloseButton.disabled=true;el.undoLastCloseButton.textContent='Geri alınıyor…';
  try{
    await runTransaction(db,async tx=>{
      const closingRef=doc(closingsCol,closing.id),closingSnap=await tx.get(closingRef),settingsSnap=await tx.get(settingsRef);
      if(!closingSnap.exists())throw new Error('missing-closing');
      const fresh=closingSnap.data()||{},settings=settingsSnap.data()||{};
      if(settings.currentBusinessDate!==businessDate||Number(settings.currentBusinessDayStartedAtMs)!==Number(businessDayStartedAtMs))throw new Error('changed');
      const update={currentBusinessDate:fresh.businessDate||closing.businessDate,currentBusinessDayStartedAtMs:Number(fresh.businessDayStartedAtMs)||startOfBusinessDateMs(fresh.businessDate||closing.businessDate),updatedAt:serverTimestamp()};
      if(fresh.previousLastClosedDate)update.lastClosedDate=fresh.previousLastClosedDate;else update.lastClosedDate=deleteField();
      tx.delete(closingRef);
      tx.set(settingsRef,update,{merge:true});
    });
    el.closeDayDialog.close();
    businessDate=closing.businessDate;businessDayStartedAtMs=Number(closing.businessDayStartedAtMs)||startOfBusinessDateMs(closing.businessDate);
    show(`${formatDate(businessDate)} iş günü tekrar aktif edildi.`);
  }catch(error){console.error(error);show(error.message==='changed'?'İş günü değiştiği için geri alma yapılamadı.':'Son kapanış geri alınamadı. Bağlantıyı ve kuralları kontrol edin.')}finally{closingDayBusy=false;if(el.undoLastCloseButton){el.undoLastCloseButton.textContent='Son Kapanışı Geri Al';await refreshUndoLastCloseBox()}}
}

function openCloseDay(){if(hasActiveBrews()){show(activeBrewWarning());return}if(orders.length){show(`Günü kapatmak için önce ${orders.length} açık Adisyonu kapatın.`);return}currentCloseReport=buildDayReport(businessDate);el.closeDayPeriod.textContent=`${formatDate(businessDate)} iş günü • ${formatDateTime(businessDayStartedAtMs)} tarihinde başladı`;el.closeDayReport.innerHTML=reportLinesHtml(currentCloseReport);el.closeDayConfirmed.checked=false;el.confirmCloseDay.disabled=true;el.closeDayDialog.showModal();refreshUndoLastCloseBox()}
function reportLinesHtml(report){return`<div class="close-day-money"><article class="is-cash"><span>Nakit</span><b>${money(report.cashIncomeTotal)}</b></article><article class="is-bank"><span>Havale</span><b>${money(report.bankIncomeTotal)}</b></article><article class="is-card"><span>Kart</span><b>${money(0)}</b></article><article class="is-tip"><span>Bahşiş</span><b>${money(report.tipTotal)}</b></article><article class="is-rounding"><span>Eksi Yuvarlama</span><b>−${money(report.roundingTotal)}</b></article></div><div class="close-day-counts"><article><span>Kapatılan Adisyon</span><b>${report.orderCount}</b></article><article><span>Satılan Ürün</span><b>${report.itemCount} Adet</b></article><article><span>İkram</span><b>${report.giftCount} Adet</b></article></div><div class="report-lines"><h3>Ürüne Göre Satış</h3>${report.products.map(p=>`<div><span>${esc(p.name)}</span><b>${p.quantity} × ${money(p.unitPrice)} = ${money(p.total)}</b></div>`).join('')||'<p>Bu iş gününde tamamlanan ürün satışı bulunmuyor.</p>'}</div>`}
async function closeBusinessDay(){if(!currentCloseReport||orders.length||closingDayBusy||!el.closeDayConfirmed.checked)return;if(hasActiveBrews()){el.closeDayDialog.close();show(activeBrewWarning());return}const closingDate=businessDate,closingRef=doc(closingsCol,`${closingDate}-${businessDayStartedAtMs}`),next=nextDate(closingDate),closedAtMs=Date.now();closingDayBusy=true;el.confirmCloseDay.disabled=true;el.confirmCloseDay.textContent='Kapatılıyor…';try{await runTransaction(db,async tx=>{const teaSnap=await tx.get(teaStateRef),existing=await tx.get(closingRef),settingsSnap=await tx.get(settingsRef);if(hasActiveBrews(teaSnap.data()||{}))throw new Error('active-brews');if(existing.exists())throw new Error('already-closed');const previousSettings=settingsSnap.data()||{};tx.set(closingRef,{...currentCloseReport,accountingMode:'report-only',cashTransferDisabled:true,cashTransferNote:'R170 sonrası para hareketleri işlem anında Kasa & Hesaplar’a yazılır. Günü Kapat sadece rapor ve iş günü kilidi oluşturur.',previousLastClosedDate:previousSettings.lastClosedDate||'',closedAtMs,closedAt:serverTimestamp(),closedBy:auth.currentUser.uid,nextBusinessDate:next});tx.set(settingsRef,{lastClosedDate:closingDate,currentBusinessDate:next,currentBusinessDayStartedAtMs:closedAtMs,updatedAt:serverTimestamp()},{merge:true})});el.closeDayDialog.close();businessDate=next;businessDayStartedAtMs=closedAtMs;show(`Gün kapatıldı. Yeni iş günü: ${formatDate(next)}`)}catch(error){console.error(error);if(error.message==='active-brews'){el.closeDayDialog.close();show('Günü kapatmadan önce aktif demliği/demlikleri bitirin.')}else show(error.message==='already-closed'?'Bu iş günü daha önce kapatılmış.':'Gün kapatılamadı. Bağlantıyı ve kuralları kontrol edin.')}finally{closingDayBusy=false;el.confirmCloseDay.textContent='Günü Kesin Olarak Kapat';el.confirmCloseDay.disabled=!el.closeDayConfirmed.checked}}
function exportCloseDayPdf(){if(!currentCloseReport)return;const c=currentCloseReport,rows=c.products.map((p,i)=>`<tr><td>${i+1}</td><td>${esc(p.name)}</td><td>${p.quantity}</td><td>${money(p.unitPrice)}</td><td>${money(p.total)}</td></tr>`).join(''),body=`<table><thead><tr><th>No</th><th>Ürün</th><th>Adet</th><th>Birim Fiyat</th><th>Toplam</th></tr></thead><tbody>${rows}</tbody></table>`;openCorporatePdf(`${formatDate(c.businessDate)} Gün Sonu Raporu`,body,[["Kapatılan Adisyon",String(c.orderCount)],["Satılan Ürün",`${c.itemCount} Adet`],["İkram",`${c.giftCount} Adet`],["Nakit",money(c.cashIncomeTotal)],["Havale",money(c.bankIncomeTotal)],["Kart",money(0)],["Bahşiş",money(c.tipTotal)]])}
function exportCloseDayExcel(){if(!currentCloseReport)return;const rows=currentCloseReport.products.map(p=>`<Row><Cell><Data ss:Type="String">${xml(p.name)}</Data></Cell><Cell><Data ss:Type="Number">${p.quantity}</Data></Cell><Cell><Data ss:Type="Number">${p.unitPrice}</Data></Cell><Cell><Data ss:Type="Number">${p.total}</Data></Cell></Row>`).join('');const content=`<?xml version="1.0"?><Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet"><Worksheet ss:Name="Gün Sonu"><Table><Row><Cell><Data ss:Type="String">Ürün</Data></Cell><Cell><Data ss:Type="String">Adet</Data></Cell><Cell><Data ss:Type="String">Birim Fiyat</Data></Cell><Cell><Data ss:Type="String">Toplam</Data></Cell></Row>${rows}<Row><Cell><Data ss:Type="String">Demlenen Çay (Demlik)</Data></Cell><Cell/><Cell/><Cell><Data ss:Type="Number">${currentCloseReport.brewedPotCount}</Data></Cell></Row><Row><Cell><Data ss:Type="String">Kapatılan Adisyon</Data></Cell><Cell/><Cell/><Cell><Data ss:Type="Number">${currentCloseReport.orderCount}</Data></Cell></Row><Row><Cell><Data ss:Type="String">Satılan Ürün</Data></Cell><Cell/><Cell/><Cell><Data ss:Type="Number">${currentCloseReport.itemCount}</Data></Cell></Row><Row><Cell><Data ss:Type="String">Nakit Gelir</Data></Cell><Cell/><Cell/><Cell><Data ss:Type="Number">${currentCloseReport.cashIncomeTotal}</Data></Cell></Row><Row><Cell><Data ss:Type="String">Banka Geliri</Data></Cell><Cell/><Cell/><Cell><Data ss:Type="Number">${currentCloseReport.bankIncomeTotal}</Data></Cell></Row></Table></Worksheet></Workbook>`;downloadBlob(content,`gun-sonu-${currentCloseReport.businessDate}.xls`,'application/vnd.ms-excel')}
function openMove(){const current=orderFor(selectedKey);if(!current)return;const options=[];for(let i=1;i<=tableCount;i++){const key=`table-${i}`;if(key!==selectedKey)options.push({key,title:`Masa ${i}`,busy:!!orderFor(key)})}orders.filter(o=>o.slotType==='named'&&o.slotKey!==selectedKey).forEach(o=>options.push({key:o.slotKey,title:o.title,busy:true}));el.moveTarget.innerHTML='<option value="">Hedef seçin</option>'+options.map(x=>`<option value="${esc(x.key)}">${esc(x.title)}${x.busy?' — Birleştir':' — Taşı'}</option>`).join('');el.moveDialog.showModal()}
async function moveOrder(e){e.preventDefault();const source=orderFor(selectedKey),targetKey=el.moveTarget.value;if(!source||!targetKey)return;const target=orderFor(targetKey);try{await runTransaction(db,async tx=>{const sourceRef=doc(ordersCol,source.id),sourceSnap=await tx.get(sourceRef);if(!sourceSnap.exists())throw new Error('missing');const sourceData=sourceSnap.data();if(target){const targetRef=doc(ordersCol,target.id),targetSnap=await tx.get(targetRef);if(!targetSnap.exists())throw new Error('missing');const targetData=targetSnap.data();tx.update(targetRef,{items:mergeItems(targetData.items||[],sourceData.items||[]),payments:[...(targetData.payments||[]),...(sourceData.payments||[])],customTitle:targetData.customTitle||sourceData.customTitle||'',title:targetData.customTitle||sourceData.customTitle||targetData.title||baseSlotTitle(targetKey),creditCustomerId:deleteField(),updatedAt:serverTimestamp()});tx.delete(sourceRef)}else tx.update(sourceRef,{slotKey:targetKey,slotType:'table',title:sourceData.customTitle||baseSlotTitle(targetKey),creditCustomerId:deleteField(),updatedAt:serverTimestamp()})});selectedKey=targetKey;el.moveDialog.close();show(target?'Adisyonlar birleştirildi; isim korundu.':'Adisyon ismiyle birlikte taşındı.')}catch(err){console.error(err);show('Taşıma İşlemi tamamlanamadı.')}}
function mergeItems(a,b){return[...a,...b].map((item,index)=>({...item,lineId:item.lineId||`${newId()}-${index}`}))}
function cancelOrder(){const o=orderFor(selectedKey);if(!o)return;const paid=orderPaid(o);if(paid>0){show(`Bu adisyonda ${money(paid)} ödeme var. Önce Son Ödeme İşlemleri'nden ödemeyi geri alın, sonra adisyonu iptal edin.`);return}el.cancelMessage.textContent=`${slotTitle(selectedKey)} Adisyonu iptal edilecek. Satış, ödeme ve stok kaydı oluşturulmayacak.`;el.cancelDialog.showModal()}
async function confirmCancelOrder(){const o=orderFor(selectedKey);if(!o)return;if(orderPaid(o)>0){el.cancelDialog.close();show(`Bu adisyonda ödeme var. Önce Son Ödeme İşlemleri'nden ödemeyi geri alın.`);return}try{await deleteDoc(doc(ordersCol,o.id));el.cancelDialog.close();showTables();show('Adisyon iptal edildi.')}catch(error){console.error(error);show('Adisyon iptal edilemedi.')}}
function itemsBill(items){return(items||[]).filter(i=>!i.complimentary).reduce((s,i)=>s+(Number(i.unitPrice)||0)*(Number(i.quantity)||0),0)}function billTotal(o){return itemsBill(o?.items||[])}function orderPaid(o){return(o?.payments||[]).reduce((s,p)=>s+(Number(p.amount)||0),0)}function orderTotal(o){return Math.max(0,billTotal(o)-orderPaid(o))}
function getBrewBusinessDate(brew){return brew?.businessDate||todayFromMs(Number(brew?.startedAtMs)||0)}
function todayFromMs(value){return new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Istanbul'}).format(new Date(value))}
function startOfBusinessDateMs(value){return new Date(`${value}T00:00:00+03:00`).getTime()}
function formatDateTime(value){return new Intl.DateTimeFormat('tr-TR',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit',hour12:false,timeZone:'Europe/Istanbul'}).format(new Date(value))}
function formatTimeFromTimestamp(value){const date=value?.toDate?.();return date?new Intl.DateTimeFormat('tr-TR',{hour:'2-digit',minute:'2-digit',hour12:false,timeZone:'Europe/Istanbul'}).format(date):'Şimdi'}
function formatInputAmount(value){return Number.isInteger(Number(value))?String(Number(value)||0):Number(value||0).toFixed(2)}
function money(v){return new Intl.NumberFormat('tr-TR',{style:'currency',currency:'TRY',minimumFractionDigits:Number(v)%1?2:0}).format(Number(v)||0)}function today(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Istanbul'}).format(new Date())}function nextDate(value){const d=new Date(`${value}T12:00:00Z`);d.setUTCDate(d.getUTCDate()+1);return d.toISOString().slice(0,10)}function formatDate(value){const [y,m,d]=String(value).split('-');return `${d}.${m}.${y}`}function newId(){return crypto.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2)}`}function formatOpened(value){const date=value?.toDate?.();return date?new Intl.DateTimeFormat('tr-TR',{hour:'2-digit',minute:'2-digit',hour12:false,timeZone:'Europe/Istanbul'}).format(date):'Şimdi'}function downloadBlob(content,name,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}function xml(v){return String(v??'').replace(/[<>&'"]/g,c=>({'<':'&lt;','>':'&gt;','&':'&amp;',"'":'&apos;','"':'&quot;'}[c]))}function updateClock(){const n=new Date();$('currentTime').textContent=new Intl.DateTimeFormat('tr-TR',{hour:'2-digit',minute:'2-digit',hour12:false,timeZone:'Europe/Istanbul'}).format(n);$('currentDate').textContent=new Intl.DateTimeFormat('tr-TR',{day:'2-digit',month:'2-digit',year:'2-digit',timeZone:'Europe/Istanbul'}).format(n).replace(/\./g,'/')}function show(m){clearTimeout(toastTimer);el.toast.textContent=m;el.toast.classList.add('show');toastTimer=setTimeout(()=>el.toast.classList.remove('show'),3000)}function esc(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function openCorporatePdf(title,body,totals){const popup=window.open('','_blank','width=1000,height=760');if(!popup)return show('PDF penceresi açılamadı.');const logo=new URL('../assets/images/logo.png',location.href).href,created=new Intl.DateTimeFormat('tr-TR',{dateStyle:'full',timeStyle:'short',timeZone:'Europe/Istanbul'}).format(new Date());popup.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>${esc(title)}</title><style>@page{size:A4;margin:15mm}*{box-sizing:border-box}body{margin:0;color:#342522;font:12px Arial,sans-serif}.watermark{position:fixed;inset:20% 15%;width:70%;height:60%;object-fit:contain;opacity:.045;z-index:-1}.head{display:flex;justify-content:space-between;gap:20px;border-bottom:3px solid #7d1b24;padding-bottom:12px}.brand img{width:90px}.brand p{margin:2px 0}.date{text-align:right}.title{text-align:center;color:#7d1b24;margin:22px 0 14px}table{width:100%;border-collapse:collapse}thead{display:table-header-group}th{background:#7d1b24;color:#fff}th,td{padding:9px;border:1px solid #d8c6ba;text-align:left}tbody tr:nth-child(even){background:#fff7ef}.totals{width:50%;margin:16px 0 0 auto;border:1px solid #d8c6ba}.totals div{display:flex;justify-content:space-between;padding:8px;border-bottom:1px solid #eaded6}.totals div:last-child{border:0;background:#fff2e2;color:#7d1b24;font-weight:bold}</style></head><body><img class="watermark" src="${logo}"><header class="head"><div class="brand"><img src="${logo}"><p><b>Fatih Ali Altınlı</b></p><p>0554 118 08 06</p><p>Ulukavak Mah. Osmancık Cad. No:285<br>Çorum/Merkez</p></div><div class="date"><b>Oluşturma Tarihi</b><p>${created}</p></div></header><h1 class="title">${esc(title)}</h1>${body}<section class="totals">${totals.map(x=>`<div><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}</section><script>window.onload=()=>setTimeout(()=>window.print(),350)<\/script></body></html>`);popup.document.close()}
